/* ===================== UI v3 — visual layer (overrides ui.js where names repeat) ===================== */
const DIFFS={easy:{l:'Easy',cash:400,c:'var(--green)'},medium:{l:'Medium',cash:250,c:'var(--gold)'},hard:{l:'Hard',cash:120,c:'var(--red)'}};
let SW=null;

/* ---------- Title & setup ---------- */
function title(){const sv=load();
 const demo={title:'Hollywood',genre:'Action',cast:{lead:null,sup:[]},dir:null,writer:null};
 $('#app').innerHTML=`<div class="marquee"><div class="lights">★ ★ ★ ★ ★</div><h1 style="margin:14px 0 6px">HOLLYWOOD<br>STUDIO SIMULATOR</h1><p class="muted">Make movies. Build an empire. Win the Golden Statue.</p></div>
 <div style="display:flex;justify-content:center;gap:10px;margin:14px 0">${['Action','Horror','Romance'].map((g,i)=>`<div style="transform:rotate(${(i-1)*6}deg)">${posterSVG({title:['Iron Protocol','The Hollow','Paris Serenade'][i],genre:g,cast:{lead:null,sup:[]},dir:null,writer:null},92)}</div>`).join('')}</div>
 <button class="btn gold" onclick="startSetup()">🎬 Found a new studio</button>
 ${sv&&!sv.over&&sv.v===3?`<button class="btn ghost" onclick="S=load();TAB='hq';render()">▶ Continue ${esc(sv.name)} · ${MON[sv.month]} ${sv.year}</button>`:''}
 <button class="btn ghost" onclick="importSave()">Load a save code</button>`}
function startSetup(){SW={step:0,name:'',logo:{text:'',sub:'Pictures',tpl:'classic',c1:'#e8b84a',c2:'#1a1206',icon:''},ceo:{id:'ceo',n:'',g:'M',age:38,look:null},diff:'medium'};
 SW.ceo.look=Object.assign({},lookOf({id:'ceo'+Math.random(),g:'M'}));setupView()}
function setupView(){const s=SW;let h=`<div class="steps">${[0,1,2].map(i=>`<i class="${i<=s.step?'on':''}"></i>`).join('')}</div>`;
 if(s.step===0){if(!s.logo.text)s.logo.text=s.name||'Silver Screen';
  h+=`<h2>Your studio</h2><div class="card center">${logoSVG(s.logo,260)}</div>
  <div class="card"><small>Studio name</small><input type="text" maxlength="24" value="${esc(s.name)}" placeholder="Silver Screen Pictures" oninput="SW.name=this.value;SW.logo.text=this.value.split(' ').slice(0,2).join(' ')||'Studio';SW.logo.icon=(this.value.match(/\\b\\w/g)||['S']).join('').slice(0,2).toUpperCase();document.getElementById('lg').innerHTML=logoSVG(SW.logo,260)"></div>
  <div class="card"><small>Logo style</small><div class="chips" style="margin-top:6px">${['classic','modern','playful','pixel','elegant','minimal'].map(t=>`<button class="${s.logo.tpl===t?'on':''}" onclick="SW.logo.tpl='${t}';setupView()">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div>
  <small style="display:block;margin-top:10px">Colours</small><div class="chips" style="margin-top:6px">${[['#e8b84a','#1a1206'],['#e05d5d','#fff4e0'],['#1f3a5f','#ffd77a'],['#0b0b10','#e8e6e0'],['#3dd68c','#08180f'],['#b07cff','#140a24'],['#f5f5f5','#7a1f2b']].map(c=>`<button style="background:${c[0]};color:${c[1]};${s.logo.c1===c[0]?'outline:2px solid #fff':''}" onclick="SW.logo.c1='${c[0]}';SW.logo.c2='${c[1]}';setupView()">Aa</button>`).join('')}</div>
  <small style="display:block;margin-top:10px">Subtitle</small><div class="chips" style="margin-top:6px">${['Pictures','Films','Studios','Entertainment','Productions','None'].map(t=>`<button class="${s.logo.sub===t?'on':''}" onclick="SW.logo.sub='${t}';setupView()">${t}</button>`).join('')}</div>
  <small style="display:block;margin-top:10px">Icon letters</small><input type="text" maxlength="3" value="${esc(s.logo.icon)}" oninput="SW.logo.icon=this.value.toUpperCase();document.getElementById('lg').innerHTML=logoSVG(SW.logo,260)"></div>
  <button class="btn gold" onclick="swNext(1)">Next: Your CEO →</button><button class="btn ghost" onclick="title()">← Back</button>`;
  h=h.replace(logoSVG(s.logo,260),`<div id="lg">${logoSVG(s.logo,260)}</div>`);}
 else if(s.step===1){const L=s.ceo.look;
  const opt=(lbl,key,arr,fmt)=>`<small style="display:block;margin-top:10px">${lbl}</small><div class="chips" style="margin-top:6px">${arr.map((v,i)=>`<button class="${L[key]===v||(typeof v==='number'&&L[key]===i&&false)?'on':''}" onclick="SW.ceo.look.${key}=${typeof v==='string'?`'${v}'`:v};setupView()">${fmt?fmt(v,i):v}</button>`).join('')}</div>`;
  h+=`<h2>Design your CEO</h2><div class="card ceo"><div>${portrait(s.ceo,110)}</div><div style="flex:1"><small>CEO name</small><input type="text" maxlength="24" value="${esc(s.ceo.n)}" placeholder="Your name" oninput="SW.ceo.n=this.value">
  <div class="seg"><button class="${s.ceo.g==='M'?'on':''}" onclick="SW.ceo.g='M';SW.ceo.look.hair='short';setupView()">Male</button><button class="${s.ceo.g==='F'?'on':''}" onclick="SW.ceo.g='F';SW.ceo.look.hair='long';SW.ceo.look.beard='none';setupView()">Female</button></div></div></div>
  <div class="card"><small>Skin tone</small><div class="chips" style="margin-top:6px">${SKINS.map((c,i)=>`<button style="background:${c};width:38px;height:32px;${L.skin===i?'outline:2px solid var(--gold)':''}" onclick="SW.ceo.look.skin=${i};setupView()"></button>`).join('')}</div>
  <small style="display:block;margin-top:10px">Hair colour</small><div class="chips" style="margin-top:6px">${HAIRC.map((c,i)=>`<button style="background:${c};width:38px;height:32px;${L.hairC===i?'outline:2px solid var(--gold)':''}" onclick="SW.ceo.look.hairC=${i};setupView()"></button>`).join('')}</div>
  <small style="display:block;margin-top:10px">Hairstyle</small><div class="chips" style="margin-top:6px">${(s.ceo.g==='F'?HAIR_F:HAIR_M).map(v=>`<button class="${L.hair===v?'on':''}" onclick="SW.ceo.look.hair='${v}';setupView()">${v}</button>`).join('')}</div>
  ${s.ceo.g==='M'?`<small style="display:block;margin-top:10px">Facial hair</small><div class="chips" style="margin-top:6px">${['none','stubble','full','mus','goatee'].map(v=>`<button class="${L.beard===v?'on':''}" onclick="SW.ceo.look.beard='${v}';setupView()">${{none:'None',stubble:'Stubble',full:'Beard',mus:'Moustache',goatee:'Goatee'}[v]}</button>`).join('')}</div>`:''}
  <small style="display:block;margin-top:10px">Outfit</small><div class="chips" style="margin-top:6px">${['tee','collar','suit','turtle'].map(v=>`<button class="${L.style===v?'on':''}" onclick="SW.ceo.look.style='${v}';setupView()">${{tee:'T-shirt',collar:'Shirt',suit:'Suit',turtle:'Turtleneck'}[v]}</button>`).join('')}</div>
  <div class="chips" style="margin-top:8px">${CLOTH.map((c,i)=>`<button style="background:${c};width:38px;height:32px;${L.cloth===i?'outline:2px solid var(--gold)':''}" onclick="SW.ceo.look.cloth=${i};setupView()"></button>`).join('')}</div>
  <div class="row" style="margin-top:10px"><span>Glasses</span><button class="btn sm ${L.glasses?'gold':'ghost'}" style="margin:0" onclick="SW.ceo.look.glasses=!SW.ceo.look.glasses;setupView()">${L.glasses?'On':'Off'}</button></div></div>
  <button class="btn gold" onclick="swNext(2)">Next: Difficulty →</button><button class="btn ghost" onclick="SW.step=0;setupView()">← Back</button>`;}
 else{h+=`<h2>Starting money</h2>${Object.keys(DIFFS).map(k=>`<div class="card opt ${s.diff===k?'sel':''}" onclick="SW.diff='${k}';setupView()"><div class="row"><b style="font-size:20px">${M(DIFFS[k].cash)}</b><span style="color:${DIFFS[k].c};font-weight:800">${DIFFS[k].l}</span></div><p class="muted" style="font-size:13px;margin-top:4px">${{easy:'Room for a few mistakes and a big first film.',medium:'A real mid-size studio. Every flop hurts.',hard:'A scrappy indie. Start small or go broke.'}[k]}</p></div>`).join('')}
  <div class="card ceo">${portrait(s.ceo,70)}<div><b>${esc(s.ceo.n||'You')}</b><div class="muted" style="font-size:13px">CEO of ${esc(s.name||'Silver Screen Pictures')}</div></div></div>
  <button class="btn gold" onclick="swNext(3)">🎬 Start the game</button><button class="btn ghost" onclick="SW.step=1;setupView()">← Back</button>`}
 $('#app').innerHTML=h;window.scrollTo(0,0)}
function finishSetup(){const s=SW;s.ceo.n=s.ceo.n||'Alex Morgan';s.logo.text=s.logo.text||'Silver Screen';s.logo.icon=s.logo.icon||'SS';
 newGame({name:s.name||'Silver Screen Pictures',logo:s.logo,ceo:s.ceo,diff:s.diff,cash:DIFFS[s.diff].cash});TAB='hq';render();
 setTimeout(()=>phoneCall('📞 Incoming call','Your assistant',`Welcome to the lot, boss! Our first move: tap <b>🎬 Make a movie</b>. Pick a script, hire a director and stars, then plan the release. Each turn is one week.`),400)}
function phoneCall(t,from,text){sfx('ring');modal(`<div class="phone"><div style="font-size:40px" class="ring">📞</div><small>${t}</small><h3 style="margin:6px 0">${esc(from)}</h3><p style="font-size:14px">${text}</p></div><button class="btn gold" onclick="modal()">Answer</button>`)}

/* ---------- Dashboard ---------- */
let CAR=0;
function hypeNow(){const ps=S.projects.filter(p=>p.dist!=='sell');const h=ps.length?sum(ps,p=>p.hype+castStats(p).star*.3)/ps.length:0;return clamp(Math.round(h*1.4+S.rep*.4),0,100)}
function hud(){return `<div class="hud"><div><small>Cash</small><b class="${S.cash<0?'neg':''}">${M(S.cash)}</b></div><div><small>Hype</small><div class="hype" style="margin-top:6px"><i style="width:${hypeNow()}%"></i></div></div><div><small>${S.stock.public?'Share':'Date'}</small><b>${S.stock.public?'$'+S.stock.price.toFixed(2):fmtShort(curDate())}</b>${S.stock.public?'':`<small style="text-transform:none;letter-spacing:0">Week ${(S.wk||0)+1} of 4</small>`}</div></div>`}
function activeCards(){const t=tNow();const list=[];
 S.projects.forEach(p=>list.push({p}));S.films.filter(f=>t-f.releaseT<=3).forEach(f=>list.push({f}));S.shows.filter(s=>s.status==='prod').forEach(s=>list.push({s}));return list}
function projCard(it){
 if(it.p){const p=it.p,ph=phaseOf(p);return `<div class="pcard" onclick="projectModal(${p.id})">${posterSVG(p,78,p.poster||defaultPoster(p))}<div style="flex:1;min-width:0"><b class="ellip" style="display:block;font-size:17px">${esc(p.title)}</b>${statusBadge(p)}<div class="statgrid"><div><small>Release</small><b>${p.dist==='sell'?'Sold':tLabel(p.releaseT)}</b></div><div class="sg-bad"><small>Spent</small><b>${M(p.paid)}</b></div><div><small>Buzz</small><b>${Math.round(p.hype)}</b></div><div><small>Test</small><b>${p.test||'—'}</b></div></div></div></div>`}
 if(it.f){const f=it.f;return `<div class="pcard" onclick="filmModal(${f.id})">${posterSVG(f,78)}<div style="flex:1;min-width:0"><b class="ellip" style="display:block;font-size:17px">${esc(f.title)}</b>${boShown(f).done?`<span class="stbadge" style="--c:#555">🏁 Run complete</span>`:`<span class="stbadge" style="--c:#d9822b">🎟️ In theaters · week ${boShown(f).n}</span>`}<div class="statgrid"><div><small>Opening</small><b>${M(f.opening)}</b></div><div class="sg-good"><small>Gross${boShown(f).done?'':' so far'}</small><b>${M(boShown(f).ww)}</b></div><div class="${boShown(f).done?(f.profit>=0?'sg-good':'sg-bad'):''}"><small>Profit</small><b>${boShown(f).done?M(f.profit):'pending'}</b></div><div class="${f.critic>=60?'sg-good':'sg-bad'}"><small>Critics/Aud</small><b>${f.critic}/${f.aud}</b></div></div></div></div>`}
 const s=it.s;return `<div class="pcard" onclick="showModal(${s.id})"><div style="width:78px;height:117px;border-radius:6px;background:linear-gradient(160deg,#1a3a4a,#0d0b10);display:flex;align-items:center;justify-content:center;font-size:40px">${TV_GENRES[s.genre].icon}</div><div style="flex:1"><b style="font-size:17px">${esc(s.title)}</b><div><span class="tag blue">Season ${s.season} in production</span></div><p class="muted" style="font-size:13px;margin-top:6px">${s.eps} episodes · ${s.mode==='weekly'?'weekly':'binge'} release · out ${tLabel(s.readyT)}</p></div></div>`}
function viewHQ(){const t=tNow(),c=CAL[S.month];const cards=activeCards();CAR=clamp(CAR,0,Math.max(0,cards.length-1));
 const tasks=studioTasks();
 return `<div class="center" style="margin-bottom:8px">${logoSVG(S.logo,220)}</div>
 <div class="ceo">${S.ceo?portrait(S.ceo,64):''}<div style="flex:1"><b>${esc(S.ceo?S.ceo.n:'You')}</b><div class="muted" style="font-size:12px">CEO of ${esc(S.name)} · prestige ${Math.round(S.rep)}</div><div class="row" style="margin-top:6px"><small>${MON[S.month]} ${S.year} · ${c.tag}</small></div></div></div>
 <div class="grid2"><button class="btn gold" style="margin:0" onclick="nextWeek()">⏭️ Next week</button><button class="btn ghost" style="margin:0;position:relative" onclick="tasksModal()">✅ Studio tasks${tasks.length?` <span class="pill" style="background:var(--red);color:#fff">${tasks.length}</span>`:''}</button></div>
<div class="row" style="margin-top:6px;gap:6px"><button class="btn sm ghost" style="margin:0;flex:1" onclick="skipMonth()">⏩ Skip to ${tLabel(tNow()+1)}</button><button class="btn sm ghost" style="margin:0;flex:1" onclick="boxOfficeModal()">🎟️ Weekend box office</button></div>
${weekendStrip()}
 <div class="card" style="margin-top:10px"><div class="row"><h3>Active projects</h3><span class="pill">${cards.length?CAR+1+' of '+cards.length:'0'}</span></div>
 ${cards.length?`<div style="margin-top:8px">${projCard(cards[CAR])}</div>${cards.length>1?`<div class="row" style="margin-top:8px"><button class="btn sm ghost" style="margin:0" onclick="CAR--;render()">◀</button><button class="btn sm ghost" style="margin:0" onclick="CAR++;render()">▶</button></div>`:''}`:'<p class="muted" style="margin-top:6px">No projects yet. Make your first movie!</p>'}</div>
 <div class="tiles"><div class="tile" onclick="startFilm()"><b>🎬</b>Make a movie</div><div class="tile" onclick="startShow()"><b>📺</b>New TV show</div><div class="tile" onclick="TAB='slate';render()"><b>🎞️</b>Released</div><div class="tile" onclick="franchiseView()"><b>🌟</b>Franchises</div><div class="tile" onclick="TAB='empire';render()"><b>🍿</b>Streaming</div><div class="tile" onclick="leaderboard()"><b>🏆</b>Top charts</div><div class="tile" onclick="lotView()"><b>🏗️</b>Studio lot</div><div class="tile" onclick="rivalsModal()"><b>🏢</b>Rival studios</div><div class="tile" onclick="socialPick()"><b>📱</b>Social media</div><div class="tile" onclick="TAB='talent';render()"><b>⭐</b>Talent</div><div class="tile" onclick="settings()"><b>⚙️</b>Settings</div></div>
 <div class="paper" onclick="newsModal()" style="cursor:pointer"><h1 style="font-size:24px">THE HOLLYWOOD LEDGER</h1><div class="center" style="font-size:11px;font-style:italic">The dream factory's paper of record · ${MON[S.month]} ${S.year}</div><div class="rule"></div>${S.news.slice(0,3).map(n=>`<div style="font-size:14px;font-weight:700;padding:5px 0;border-bottom:1px solid #1d1a1422">${n.s}</div>`).join('')}<div class="center" style="font-size:12px;margin-top:6px">Tap to read more ▾</div></div>
 ${S.social.length?`<div class="card"><h3>📱 Trending</h3>${S.social.slice(0,3).map(p=>`<div class="news"><b style="font-size:13px">@${esc(p.h)}</b><div>${p.s}</div><small>♥ ${p.l.toLocaleString()}</small></div>`).join('')}</div>`:''}
 <button class="btn ghost sm" onclick="settings()">⚙️ Menu</button>`}
function studioTasks(){const t=tNow(),out=[];
 S.projects.forEach(p=>{const ph=phaseOf(p);if(!p.poster&&(ph==='post'||ph==='ready')&&p.dist!=='sell')out.push({p,l:'Design the poster',f:`posterDesigner(${p.id})`});if(!p.trailer&&(ph==='post'||ph==='ready')&&p.dist!=='sell')out.push({p,l:'Release a trailer',f:`trailerNow(${p.id})`})});
 S.shows.filter(s=>s.renew).forEach(s=>out.push({s,l:'Renew or cancel',f:`showModal(${s.id})`}));
 if(S.month>=8)S.films.filter(f=>yearOf(f.releaseT)===S.year&&f.critic>=72&&!f.fyc&&f.dist!=='sell').forEach(f=>out.push({f,l:'Awards campaign?',f2:1,f:`filmModal(${f.id})`}));
 return out}
function tasksModal(){const ts=studioTasks();modal(`<h3>✅ Studio tasks</h3><p class="muted" style="font-size:13px">${ts.length} task${ts.length===1?'':'s'} waiting.</p>${ts.map(x=>{const o=x.p||x.s||x.f;return `<div class="card row"><div><b>${esc(o.title)}</b><div><span class="tag blue">${x.l}</span></div></div><button class="btn sm gold" style="margin:0" onclick="modal();${x.f}">Go</button></div>`}).join('')||'<p class="muted card">All caught up. Advance to next month!</p>'}<button class="btn ghost" onclick="modal()">Close</button>`)}
function newsModal(){modal(`<div class="paper"><h1>THE HOLLYWOOD LEDGER</h1><div class="center" style="font-size:11px;font-style:italic">${MON[S.month]} ${S.year}</div><div class="rule"></div>${S.news.slice(0,20).map(n=>`<div style="padding:7px 0;border-bottom:1px solid #1d1a1422"><span style="font-size:10px;letter-spacing:1px;background:#1d1a14;color:#f3ead7;padding:1px 6px;border-radius:3px">${tLabel(n.t)}</span><div style="font-weight:700;margin-top:3px">${n.s}</div></div>`).join('')}</div><button class="btn ghost" onclick="modal()">Close</button>`)}
function leaderboard(){const y=S.year-1;const ms=S.market[y]||[];const films=S.films.slice().sort((a,b)=>b.ww-a.ww).slice(0,10);const acts=S.people.actors.slice().sort((a,b)=>b.star-a.star).slice(0,10);
 modal(`<h3>🏆 Top charts</h3><div class="card"><b>Top studios (${y})</b>${ms.length?ms.map((r,i)=>`<div class="row news"><span>#${i+1} ${r.me?'<b class="gold">'+esc(r.n)+'</b>':esc(r.n)}</span><span>${M(r.dom)}</span></div>`).join(''):'<p class="muted">Available after your first full year.</p>'}</div>
 <div class="card"><b>Your top movies</b>${films.map((f,i)=>`<div class="pcard news">${posterSVG(f,34)}<div style="flex:1"><b>${esc(f.title)}</b><div class="muted" style="font-size:12px">${M(f.ww)} · 🍅${f.critic}%</div></div></div>`).join('')||'<p class="muted">No releases yet.</p>'}</div>
 <div class="card"><b>Top actors</b>${acts.map((a,i)=>`<div class="pcard news">${portrait(a,36)}<div style="flex:1"><b>${esc(a.n)}</b><div class="muted" style="font-size:12px">Star ${a.star} · ${a.hits} hits</div></div></div>`).join('')}</div><button class="btn ghost" onclick="modal()">Close</button>`)}
function franchiseView(){modal(`<h3>🌟 Your franchises</h3>${S.franchises.map(fr=>{const fl=S.films.filter(f=>f.fid===fr.id);return `<div class="card"><div class="row"><b>${esc(fr.name)}</b><span class="tag">${fr.parts} film${fr.parts>1?'s':''}</span></div><div class="row" style="margin-top:4px"><small>Fans ${Math.round(fr.fans)}</small><small class="pos">${M(sum(fl,f=>f.profit))} profit</small></div>${bar(fr.fans,'#ff8a5c')}<div style="display:flex;gap:6px;margin-top:8px;overflow-x:auto">${fl.map(f=>posterSVG(f,44)).join('')}</div></div>`}).join('')||'<p class="muted card">Hits and adaptations become franchises. Then sequels, spinoffs and crossovers appear when you make a movie.</p>'}<button class="btn ghost" onclick="modal()">Close</button>`)}

/* ---------- People cards & negotiation ---------- */
function personCard(x,sel,onclick,isA,locked,extra){const fee=isA?actorFee(x):crewFee(x,W._role);const deal=W&&W.deals&&W.deals[x.id];
 return `<div class="card opt ${sel?'sel':''} ${locked?'locked':''}" onclick="${locked?'':onclick}"><div class="pcard">${portrait(x,56)}<div style="flex:1;min-width:0"><div class="row"><b class="ellip">${natOf(x.nat)[1]} ${esc(x.n)}</b><b>${M(deal?deal.fee:fee)}</b></div><small style="text-transform:none;letter-spacing:0">${x.age} yrs · ${isA?(x.g==='F'?'Female':'Male'):ROLE_LBL[W._role||'directors'].replace(/s$/,'')}${deal?` · <span class="pos">signed${deal.share?' +'+deal.share+'%':''}</span>`:''}</small></div></div>
 <div style="margin-top:8px">${isA?`<div class="row" style="font-size:12px"><span>⭐ Acting</span><span>${x.skill}</span></div>${bar(x.skill)}<div class="row" style="font-size:12px;margin-top:4px"><span>💜 Star power</span><span>${x.star}</span></div>${bar(x.star,'#b07cff')}`:`<div class="row" style="font-size:12px"><span>⭐ Craft</span><span>${x.skill}</span></div>${bar(x.skill)}<div class="row" style="font-size:12px;margin-top:4px"><span>💜 Fame</span><span>${x.fame}</span></div>${bar(x.fame,'#b07cff')}`}</div>
 <div class="tags">${(x.traits||[]).map(t=>`<span class="tag ${TRAITS[t].good?'good':'bad'}">${TRAITS[t].i} ${TRAITS[t].l}</span>`).join('')}</div><div class="tags"><span class="tag blue" onclick="event.stopPropagation();openPerson('${x.id}')">ⓘ Profile</span><span class="tag ${W.script&&x.spec===W.script.genre?'good':''}">${GEN[x.spec].icon} ${x.spec}</span>${isA?`<span class="tag ${x.star>70?'hot':''}">${x.star>80?'🔥 Huge fanbase':x.star>55?'Big fanbase':x.star>30?'Rising fanbase':'Small fanbase'}</span>`:''}${x.hits?`<span class="tag good">${x.hits} hits</span>`:''}${extra||''}${busy(x)?`<span class="tag bad">⏳ Busy ${x.busy-tNow()+1} mo</span>`:locked&&!extra?'<span class="tag bad">🔒 Wants a bigger studio</span>':'<span class="tag good">✔ Available</span>'}</div></div>`}
function wizFees(w){let f=w.script.cost;const dl=w.deals||{};const fee=(id,role)=>{if(dl[id])return dl[id].fee;const p=person(id);return p?(role==='actors'?actorFee(p):crewFee(p,role)):0};
 f+=fee(w.dir,'directors');[w.lead,w.co].concat(w.sup,w.leads2||[],w.cos2||[]).filter(Boolean).forEach(id=>f+=fee(id,'actors'));
 if(w.comp)f+=fee(w.comp,'composers');if(w.dp)f+=fee(w.dp,'dps');if(w.rewriter)f+=fee(w.rewriter,'writers');return f+(w.pen||0)}
let NG=null;
function negotiate(id,role,slot){const p=person(id);const ask=role==='actors'?actorFee(p):crewFee(p,role);
 const wantShare=Math.max(role==='actors'&&p.star>78?Math.round((p.star-70)/3):0,hasT(p,'greedy')?5:0);const fr=W.script.fid?S.franchises.find(x=>x.id===W.script.fid):null;
 const prem=fr&&S.films.some(f=>f.fid===fr.id&&(f.cast.lead===id||f.dir===id))?1.25:1;
 NG={id,role,slot,ask:+(ask*prem).toFixed(2),offer:+(ask*prem*.85).toFixed(2),share:0,want:wantShare,tries:0,prem};negView()}
function negVal(){return (NG.offer+NG.share*NG.ask*.06)/NG.ask}
function negView(){const p=person(NG.id);const v=negVal();const col=v>=1?'var(--green)':v>=.85?'var(--gold)':'var(--red)';
 const avail=S.cash+creditLimit()-committed()-wizFees(W);
 modal(`<div class="center">${portrait(p,80)}<h3 style="margin-top:6px">Negotiating with ${esc(p.n)}</h3></div>
 <div class="card" style="background:var(--card2);border:2px solid var(--blue)"><div class="row"><span>Available budget</span><b>${M(avail)}</b></div></div>
 <div class="card center"><small>${esc(p.n)}</small><p style="margin-top:4px">${NG.tries>0?(v<.7?'"Is this a joke? Call me when you are serious."':'"Not quite there. Sweeten the deal."'):NG.want?`"I want ${NG.want}% of the profits on this one."`:'"How much are you offering?"'}</p>${NG.prem>1?'<small style="text-transform:none" class="gold">Franchise premium: returning talent knows their worth</small>':''}</div>
 <div class="card"><div class="row"><small>Expected offer</small><b>${M(NG.ask)}</b></div><div class="row" style="margin-top:6px"><small>Your offer value</small><b style="color:${col}">${Math.round(v*100)}% · ${M(NG.offer+NG.share*NG.ask*.06)}</b></div><div class="meter"><i style="width:${clamp(v*80,0,100)}%;background:${col}"></i></div></div>
 <div class="card"><small>Upfront salary</small><div class="row" style="margin-top:6px"><button class="btn sm ghost" style="margin:0" onclick="NG.offer=Math.max(.05,+(NG.offer-NG.ask*.05).toFixed(2));negView()">−</button><b class="big">${M(NG.offer)}</b><button class="btn sm ghost" style="margin:0" onclick="NG.offer=+(NG.offer+NG.ask*.05).toFixed(2);negView()">+</button></div>
 ${NG.role==='actors'||NG.role==='directors'?`<small style="display:block;margin-top:10px">Profit share: ${NG.share}%</small><input type="range" min="0" max="20" value="${NG.share}" onchange="NG.share=+this.value;negView()">`:''}</div>
 <button class="btn gold" onclick="negOffer()">🤝 Make offer</button><button class="btn ghost" onclick="modal()">Cancel</button>`)}
function negOffer(){const v=negVal();const okShare=NG.share>=NG.want||v>=1.15;
 const chance=!okShare?.15:v>=1?1:v>=.85?(v-.7)/.3:v>=.7?.15:0;NG.tries++;
 if(Math.random()<chance){const p=person(NG.id);W.deals=W.deals||{};W.deals[NG.id]={fee:NG.offer,share:NG.share};
  if(NG.role==='actors')assignCast(NG.id,NG.slot);else W[NG.slot]=NG.id;
  modal(`<div class="popcard"><div style="font-size:40px">✅</div><h3>Contract accepted!</h3><div class="center" style="margin:8px 0">${portrait(p,64)}</div><b>${esc(p.n)}</b>
  <div class="card" style="margin-top:10px;text-align:left"><div class="row"><span class="muted">Upfront salary</span><b>${M(NG.offer)}</b></div><div class="row"><span class="muted">Profit share</span><b>${NG.share}%</b></div></div>
  <div class="card warnbox" style="text-align:left"><b>⚠️ Removal penalty</b><p style="font-size:13px;margin-top:4px">Firing ${esc(p.n)} from this film costs ${M(NG.offer*.3)} (30% of salary).</p></div></div><button class="btn gold" onclick="modal();wiz()">Confirm</button>`)}
 else if(NG.tries>=3||v<.6){const p=person(NG.id);p.snub=tNow()+1;modal(`<div class="popcard"><div style="font-size:40px">🚪</div><h3>${esc(p.n)} walked away</h3><p class="muted">"My agent will hear about this."</p></div><button class="btn ghost" onclick="modal();wiz()">OK</button>`)}
 else{NG.ask=+(NG.ask*1.04).toFixed(2);negView()}}
function assignCast(id,slot){if(slot==='sup'){if(!W.sup.includes(id)&&W.sup.length<6)W.sup.push(id)}else if(slot==='lead'){if(!W.lead)W.lead=id;else if(W.leads2.length<2)W.leads2.push(id)}else if(slot==='co'){if(!W.co)W.co=id;else if(W.cos2.length<2)W.cos2.push(id)}else W[slot]=id}
function fireCast(id){const d=W.deals&&W.deals[id];if(d){W.pen=(W.pen||0)+d.fee*.3;delete W.deals[id]}if(W.lead===id){W.lead=W.leads2.shift()||null}if(W.co===id){W.co=W.cos2.shift()||null}W.leads2=W.leads2.filter(x=>x!==id);W.cos2=W.cos2.filter(x=>x!==id);W.sup=W.sup.filter(x=>x!==id);wiz()}

