function makeFranchise(id,name){const f=S.films.find(x=>x.id===id);const fr={id:'fr'+f.id,name:name||f.title,genre:f.genre,fans:clamp((f.aud-40)/1.5+(f.profit>0?10:0),5,60),parts:1,universe:false,films:[f.id]};S.franchises.push(fr);f.fid=fr.id;modal();pickSequel(fr.id)}
function greenlight(){W.acts=W.acts3.filter(Boolean);
 const p=buildProject(W);S.cash-=p.fees;p.deals=W.deals;p.shares=sum(Object.values(W.deals||{}),d=>d.share||0);
 const t=tNow();allCast(p.cast).forEach(id=>{const a=person(id);a.busy=t+p.sch.pre+p.sch.shoot});if(p.lateNote)addNews(`⏰ ${esc(p.lateNote)} keeps showing up late; <b>${esc(p.title)}</b> slips a month.`);
 const d=person(W.dir);d.busy=t+p.sch.total;[W.comp,W.dp,W.rewriter].filter(Boolean).forEach(id=>person(id).busy=t+p.sch.total);
 if(!W.script.own)S.scripts=S.scripts.filter(x=>x!==W.script);S.projects.push(p);
 S.receivables.push({t:t+p.sch.total,amt:p.rebate*(1-p.cofi),label:p.title+' tax rebate'});
 addNews(`🟢 ${esc(S.name)} greenlights <b>${esc(p.title)}</b> (${p.genre}${p.g2?'/'+p.g2:''}, ${M(p.spend)}) — ${esc(pname(p.dir))} directing ${esc(pname(p.cast.lead))}${p.cast.co?' and '+esc(pname(p.cast.co)):''}.`);
 save();TAB='hq';CAR=0;render();addInbox('🎬',pname(p.dir),`Pre-production begins on ${esc(p.title)}`,`"Thrilled to be on board <b>${esc(p.title)}</b>! Pre-production starts now."`)}

/* ---------- Poster designer ---------- */
let PD=null;
function posterDesigner(id){const p=S.projects.find(x=>x.id===id);PD={id,d:Object.assign({},p.poster||defaultPoster(p))};pdView()}
function pdView(){const p=S.projects.find(x=>x.id===PD.id);const d=PD.d;const sc=posterScore(p,d);
 const chips=(lbl,key,obj)=>`<small style="display:block;margin-top:10px">${lbl}</small><div class="chips" style="margin-top:6px">${Object.keys(obj).map(k=>`<button class="${d[key]===k?'on':''}" onclick="PD.d.${key}='${k}';pdView()">${obj[k]}</button>`).join('')}</div>`;
 const arr=a=>a.reduce((o,k)=>(o[k]=k[0].toUpperCase()+k.slice(1),o),{});
 modal(`<h3>🖼️ Design your movie poster</h3><div class="center" style="margin:8px 0">${posterSVG(p,190,d)}</div>
 <div class="card"><div class="row"><b>Poster quality</b><span class="big" style="color:${sc.score>=70?'var(--green)':sc.score>=50?'var(--gold)':'var(--red)'}">${sc.score}</span></div>${sc.reasons.map(r=>`<div class="row" style="font-size:12px"><span class="muted">${r[1]}</span><b>${r[0]}</b></div>`).join('')}</div>
 <div class="grid2"><button class="btn ghost" style="margin:0" onclick="pdRandom()">🎲 Randomize</button><button class="btn ghost" style="margin:0" onclick="pdBest()">✨ Auto-best</button></div>
 <div class="card" style="margin-top:8px"><small>Tagline</small><input type="text" maxlength="40" value="${esc(d.tagline||'')}" placeholder="e.g. Some secrets never die" onchange="PD.d.tagline=this.value;pdView()">
 ${chips('Layout','layout',P_LAYOUTS)}${chips('Backdrop','bg',arr(P_BGS))}${chips('Colours','pal',arr(Object.keys(P_PALS)))}${chips('Lettering','font',Object.keys(P_FONTS).reduce((o,k)=>(o[k]=P_FONTS[k][1],o),{}))}${chips('Drawing','art',arr(P_ART))}
 <small style="display:block;margin-top:10px">Title size</small><input type="range" min="18" max="44" value="${d.titleSize||30}" onchange="PD.d.titleSize=+this.value;pdView()"><small>Title position</small><input type="range" min="60" max="250" value="${d.titleY||200}" onchange="PD.d.titleY=+this.value;pdView()">
 <small style="display:block;margin-top:10px">Designed by</small><div class="seg">${[['Art dept · free',0],['Agency · '+M(.5*I()),1],['Top designer · '+M(1.5*I()),2]].map(t=>`<button class="${(d.tier||0)===t[1]?'on':''}" onclick="PD.d.tier=${t[1]};pdView()">${t[0]}</button>`).join('')}</div></div>
 <button class="btn gold" onclick="pdSave()">✅ Finalize poster</button><button class="btn ghost" onclick="modal()">Cancel</button>`)}
function pdRandom(){const d=PD.d;d.layout=pick(Object.keys(P_LAYOUTS));d.bg=pick(P_BGS);d.pal=pick(Object.keys(P_PALS));d.font=pick(Object.keys(P_FONTS));d.art=pick(P_ART);pdView()}
function pdBest(){const p=S.projects.find(x=>x.id===PD.id);let best=null,bs=-1;for(let i=0;i<300;i++){const d=Object.assign({},PD.d,{layout:pick(Object.keys(P_LAYOUTS)),bg:pick(P_BGS),pal:pick(Object.keys(P_PALS)),font:pick(Object.keys(P_FONTS)),art:pick(P_ART)});const s=posterScore(p,d).score;if(s>bs){bs=s;best=d}}PD.d=best;pdView()}
function pdSave(){const p=S.projects.find(x=>x.id===PD.id);const c=[0,.5,1.5][PD.d.tier||0]*I();S.cash-=c;p.paid+=c;p.poster=PD.d;const sc=posterScore(p,PD.d).score;addNews(`🖼️ The poster for <b>${esc(p.title)}</b> is out. ${sc>=75?'Fans love it.':sc<50?'Designers online are mocking it.':'Reactions are mixed.'}`);save();modal();render()}

/* ---------- Trailer card ---------- */
function trailerNow(id){const p=S.projects.find(x=>x.id===id);if(!p.trailer)dropTrailer(p);save();showTrailer(p)}
function showTrailer(p){const tr=p.trailer;const likes=Math.round(tr.views*1000*.05*tr.like/100),dis=Math.round(tr.views*1000*.05*(100-tr.like)/100);const buzz=Math.round((tr.like-55)/5+Math.min(5,tr.views/10));
 modal(`<div class="vid"><div class="row"><b style="font-size:18px">Vid<span style="background:#7b2cff;color:#fff;border-radius:8px;padding:0 6px">Stream</span></b><button class="btn sm ghost" style="margin:0" onclick="modal();render()">✕</button></div>
 <div class="thumb" style="margin-top:8px">${posterSVG(p,70,p.poster||defaultPoster(p))}<div style="flex:1;color:#fff"><div class="play">▶</div><small style="color:#cbb">A MOTION PICTURE</small><div style="font-weight:800;font-size:16px">${esc(p.title)}</div>${p.poster&&p.poster.tagline?`<div style="color:#ffb35c;font-size:12px">${esc(p.poster.tagline)}</div>`:''}</div></div>
 <div style="font-weight:800;margin-top:8px">${esc(p.title)} Official Trailer | Starring ${esc(pname(p.cast.lead))}</div>
 <div class="row" style="margin-top:6px"><span>${S.logo?`<b>${esc(S.logo.text)}</b>`:esc(S.name)} ✔<br><small style="color:#554;text-transform:none">Official channel</small></span><span style="background:#fff;border-radius:16px;padding:4px 10px;font-size:13px">👍 ${fmtK(likes)} | 👎 ${fmtK(dis)}</span></div>
 <div class="meta"><b>${fmtK(Math.round(tr.views*1e6))} views · <span style="color:${buzz>=0?'#1a7a3a':'#a11'}">${buzz>=0?'+':''}${buzz} buzz</span></b><p style="margin-top:4px">${buzz>=6?'Social media is on fire! The trailer has fans and casual audiences buzzing.':buzz>=0?'A solid reaction. Fans are curious.':'Fans are criticizing the edit and tone. The backlash is hurting anticipation.'}</p></div></div>
 <button class="btn ghost" onclick="modal();render()">Close</button>`)}
function fmtK(n){return n>=1e6?(n/1e6).toFixed(1)+'M':n>=1e3?(n/1e3).toFixed(1)+'K':String(n)}

/* ---------- Project modal (adds poster & trailer) ---------- */
function projectModal(id){const p=S.projects.find(x=>x.id===id);if(!p)return;const ph=phaseOf(p),t=tNow();
 const canRe=(ph==='post'||ph==='ready')&&!p.reshot&&!p.acquired&&p.dist!=='sell';const reC=+(p.spend*.08).toFixed(1);
 const canTour=!p.tour&&p.releaseT-t<=2&&p.dist!=='sell'&&!ev('sag');const stg=['pre','shoot','post','ready'].indexOf(ph);
 modal(`<div class="pcard">${posterSVG(p,90,p.poster||defaultPoster(p))}<div><h3>${esc(p.title)}</h3><p class="muted" style="font-size:13px">${p.genre}${p.g2?' / '+p.g2:''} · ${p.rating} · ${p.rt} min</p><div style="display:flex;gap:4px;margin-top:6px">${[p.cast.lead,p.cast.co].concat(p.cast.sup).filter(Boolean).slice(0,5).map(id=>portrait(person(id),30)).join('')}</div></div></div>
 ${stageBar(p)}
 ${p.acts&&p.acts.length?`<div class="card" style="margin-top:8px"><small>Story</small>${p.acts.map((a,i)=>`<div style="font-size:13px;margin-top:3px"><span class="muted">${ACTS[i].split(' · ')[1]}:</span> ${esc(a)}</div>`).join('')}</div>`:''}
 <div class="card">${[['Status',PH[ph]],['Release',p.dist==='stream'?'Streaming · '+tLabel(p.releaseT):p.dist==='sell'?'Sold to streamer':tLabel(p.releaseT)+' · '+(p.dist==='platform'?'Platform':'Wide')],['Budget / P&A',M(p.spend)+' / '+M(p.mkt)],['Spent so far',M(p.paid)],['Buzz',Math.round(p.hype)],
   p.test?['Test screening',p.test+'/100']:null,p.poster?['Poster score',posterScore(p,p.poster).score]:null].filter(Boolean).map(r=>`<div class="row" style="margin-top:5px"><span class="muted">${r[0]}</span><b>${r[1]}</b></div>`).join('')}</div>
 ${(ph==='post'||ph==='ready')&&p.dist!=='sell'?`<button class="btn ${p.poster?'ghost':'gold'}" onclick="posterDesigner(${id})">🖼️ ${p.poster?'Edit':'Design'} the poster</button><button class="btn ghost" onclick="${p.trailer?`showTrailer(S.projects.find(x=>x.id===${id}))`:`trailerNow(${id})`}">🎞️ ${p.trailer?'View trailer stats':'Release the trailer'}</button>`:''}
 ${canTour?`<button class="btn ghost" onclick="pressTour(${id})">🎤 Press tour (${M(1.5*I())})</button>`:''}
 ${canRe?`<button class="btn ghost" onclick="reshoot(${id})">🎥 Reshoots (${M(reC)}, +1 month)</button>`:''}
 ${p.dist!=='sell'?`<button class="btn ghost" onclick="moveDate(${id})">📅 Change release date</button>`:''}
 ${svcLive()&&p.dist!=='stream'&&p.dist!=='sell'?`<button class="btn ghost" onclick="toStream(${id})">📡 Premiere on ${esc(S.streaming.name)}</button>`:''}
 ${p.dist!=='sell'?`<button class="btn ghost" onclick="auctionView(${id})">💰 Streaming auction</button>`:''}
 <button class="btn ghost" onclick="modal()">Close</button>`)}
function auctionView(id){const p=S.projects.find(x=>x.id===id);const base=streamOffer(p);const bidders=shuffle([TECH_STREAMER.n].concat(S.rivals.filter(r=>r.alive&&r.svc).map(r=>r.svc))).slice(0,3);
 let bids=bidders.map(b=>({b,v:+(base*R(.7,1.15)).toFixed(1)})).sort((a,b)=>a.v-b.v);let i=0;
 modal(`<div class="popcard"><h3>STREAMING AUCTION</h3><b>${esc(p.title)}</b><div id="bid" class="card" style="background:#fdf3d8;color:#1b1206;margin-top:10px"><small style="color:#554">Current bid</small><div class="big" id="bidder">…</div><div class="big pos" id="bidv"></div></div><div id="bidbtns"></div></div>`);
 const step=()=>{if(i<bids.length){const b=bids[i++];$('#bidder').textContent=b.b;$('#bidv').textContent=M(b.v);setTimeout(step,900)}else{const w=bids[bids.length-1];$('#bid').insertAdjacentHTML('afterbegin','<small style="color:#1a7a3a">WINNING BID · 2-year deal</small>');
  $('#bidbtns').innerHTML=`<button class="btn gold" onclick="acceptBid(${id},${w.v},'${esc(w.b)}')">ACCEPT ${M(w.v)}</button><button class="btn ghost" onclick="modal()">Keep it for theaters</button>`}};setTimeout(step,500)}
function acceptBid(id,v,b){const p=S.projects.find(x=>x.id===id);p.sellFee=v;p.dist='sell';p.releaseT=Math.max(tNow()+1,p.startT+p.sch.total);addNews(`📺 ${esc(S.name)} sells <b>${esc(p.title)}</b> to ${esc(b)} for ${M(v)}.`);save();modal();render()}

/* ---------- Release sequence ---------- */
function releaseScreen(f){S.films.includes(f)||S.films.push(f);save();
 if(f.dist==='stream'||f.dist==='sell'){return reviewStage(f)}
 $('#app').innerHTML=`<div class="center lights" style="padding:8px">★ OPENING NIGHT ★</div>${cinemaScene(f)}<div class="popcard"><small>Opening weekend · ${esc(f.title)}</small><div class="countup" id="cu">$0M</div><small>Box office · ${(f.screens||4).toLocaleString()} screens</small></div><button class="btn gold" id="cn" style="visibility:hidden" onclick="reviewStage(S.films.find(x=>x.id===${f.id}))">Continue →</button>`;
 window.scrollTo(0,0);let v=0;const target=f.opening;const st=Math.max(target/40,.05);const tk=setInterval(()=>{v=Math.min(target,v+st);const e=$('#cu');if(e)e.textContent=M(v);if(v>=target){clearInterval(tk);sfx(f.profit>0||target>20*I()?'cash':'flop');const b=$('#cn');if(b)b.style.visibility='visible';if(target>40*I()&&document.body)document.body.insertAdjacentHTML('beforeend',confetti(50));setTimeout(()=>{const c=document.querySelector('.confetti');if(c)c.remove()},4000)}},40)}
function reviewStage(f){const stars=s=>'★'.repeat(Math.round(s/20))+'☆'.repeat(5-Math.round(s/20));
 const aspects=['Performances','Story & script','Direction & craft','Entertainment'];
 $('#app').innerHTML=`<div class="paper"><h1>THE DAILY REEL</h1><div class="center" style="font-size:11px;font-style:italic">Reviews · ${tLabel(f.releaseT)}</div><div class="rule"></div>
 <div class="pcard">${posterSVG(f,90)}<div><div style="font-size:22px;font-weight:900">${esc(f.title)}</div><div style="font-size:12px">${f.genre}${f.g2?' / '+f.g2:''} · ${f.rating} · ${f.rt||120} min</div><div style="font-size:12px">Dir. ${esc(pname(f.dir))}</div></div></div>
 ${(f.reviews||[]).map((r,i)=>`<div class="crit"><div class="row"><b>${r.o}</b><span class="stars">${stars(r.s)}</span></div><div style="font-size:11px;text-transform:uppercase;letter-spacing:1px">${aspects[i]}</div><i>"${r.q}"</i></div>`).join('')}</div>
 <div class="popcard"><div style="font-size:30px">⭐</div><h3>REVIEWS ARE IN!</h3><div class="grid2" style="margin-top:10px"><div><small>Critics</small><div class="countup reveal" style="color:${f.critic>=60?'var(--green)':'var(--red)'}">${f.critic}</div></div><div id="aud" style="opacity:0;transition:opacity .6s"><small>Audience</small><div class="countup" style="color:${f.aud>=60?'var(--green)':'var(--red)'}">${f.aud}</div></div></div>
 <b id="verd" style="opacity:0;transition:opacity .6s;display:block;margin-top:8px;color:${f.critic>=60&&f.aud>=60?'var(--green)':f.critic<50&&f.aud<50?'var(--red)':'var(--gold)'}">${f.critic>=70&&f.profit>0?'CRITICAL AND COMMERCIAL SUCCESS!':f.critic>=70?'CRITICS LOVE IT':f.aud>=70?'AUDIENCES LOVE IT':f.critic<45&&f.aud<45?'PANNED BY EVERYONE':'MIXED REACTIONS'}</b></div>
 <button class="btn gold" onclick="finalStage(S.films.find(x=>x.id===${f.id}))">See full results →</button>`;
 window.scrollTo(0,0);setTimeout(()=>{const a=$('#aud');if(a)a.style.opacity=1},900);setTimeout(()=>{const a=$('#verd');if(a)a.style.opacity=1},1500)}
function finalStage(f){$('#app').innerHTML=hud()+`<div class="center" style="padding:6px 0"><div class="lights">★ FINAL TALLY ★</div><h2 style="font-size:32px;margin-top:4px">${verdict(f)}</h2></div><div class="center" style="margin-bottom:8px">${posterSVG(f,130)}</div>`+filmReport(f,'queue')+
 `<div class="card"><small>📱 Social reaction</small>${S.social.filter(p=>p.s.includes(esc(f.title))).slice(0,3).map(p=>`<div class="news"><b style="font-size:13px">@${esc(p.h)}</b><div>${p.s}</div><small>♥ ${p.l.toLocaleString()}</small></div>`).join('')}</div><button class="btn gold" onclick="runQueue()">Continue →</button>`;save();window.scrollTo(0,0)}
function filmModal(id){const f=S.films.find(x=>x.id===id);if(f)modal(`<div class="center" style="margin-bottom:8px">${posterSVG(f,140)}</div>`+filmReport(f,'modal')+`<button class="btn ghost" onclick="modal()">Close</button>`)}

/* ---------- Awards ceremony ---------- */
let AW=null;
function awardsScreen(top,head,count,res,tip){AW={top,head,res,i:-1,tip,count};awStep()}
function awStep(){const A=AW;
 if(A.i<0){ $('#app').innerHTML=stageBG(`<div class="lights">${A.top}</div><div style="margin:14px auto">${statue(130)}</div><h2>${A.head}</h2><p style="font-size:14px">${A.count?`Your studio has <b>${A.res.length}</b> nomination${A.res.length===1?'':'s'} tonight.`:'You had nothing eligible this year.'}</p>${!A.res.length&&A.count?`<p class="muted" style="font-size:12px">${A.tip}</p>`:''}`)+
   (A.res.length?`<button class="btn gold" onclick="AW.i=0;AW.rev=0;awStep()">🎤 Begin the ceremony</button><button class="btn ghost" onclick="awResults()">Skip to results</button>`:`<button class="btn gold" onclick="runQueue()">Continue →</button>`);window.scrollTo(0,0);return}
 if(A.i>=A.res.length)return awResults();
 const r=A.res[A.i];if(!r._nom){r._nom=[{t:r.film.title,me:1,f:r.film}].concat([0,1,2].map(k=>({t:k===0?r.rival:genTitle(pick(['Drama','Biopic','Thriller','Sci-Fi'])),studio:pick(S.rivals.filter(x=>x.alive).map(x=>x.n).concat(['Lantern Releasing']))})));r._ord=shuffle(r._nom)}
 const nominees=r._nom,order=r._ord;const winner=r.win?nominees[0]:nominees[1];
 const pid=r.cat.includes('Act')||r.cat.includes('Perf')?r.film.cast&&r.film.cast.lead:r.cat==='Best Director'?r.film.dir:null;
 const nomHTML=(rev)=>order.map(n=>`<div class="nominee ${rev&&n===winner?'win':''}">${n.f?posterSVG(n.f,30):`<div style="width:30px;height:45px;border-radius:4px;background:#333"></div>`}<div style="flex:1"><b>${esc(n.t)}</b><div style="font-size:11px" class="muted">${n.me?esc(S.name)+(pid?' · '+esc(pname(pid)):''):esc(n.studio)}</div></div>${rev&&n===winner?'🏆':''}</div>`).join('');
 if(!A.rev){sfx('drum');$('#app').innerHTML=stageBG(`<small class="lights">${A.top}</small><h3 style="margin:8px 0">${r.cat.toUpperCase()}</h3><p style="font-size:13px">And the nominees are…</p>${nomHTML(false)}<div class="envelope"></div><div class="lights">AND THE WINNER IS…</div><div class="spinner"></div>`)+`<button class="btn ghost" onclick="awResults()">Skip to results</button>`;
  window.scrollTo(0,0);clearTimeout(A.tm);A.tm=setTimeout(()=>{AW.rev=1;awStep()},2200);return}
 $('#app').innerHTML=stageBG(`<small class="lights">${A.top}</small><h3 style="margin:8px 0">${r.cat.toUpperCase()}</h3><div class="reveal">${statue(70)}</div><div class="popcard" style="background:#2a1d0a;color:#f3ece0"><div style="font-size:12px;letter-spacing:2px" class="gold">THE WINNER IS</div><div style="font-size:22px;font-weight:900;margin:4px 0">${esc(winner.t)}</div>${winner.me&&pid?`<div class="center">${portrait(person(pid),60)}</div><div>${esc(pname(pid))}</div>`:''}<small style="text-transform:none">${winner.me?esc(S.name):esc(winner.studio)}</small>${winner.me?`<div style="margin-top:8px"><span class="pill" style="background:var(--gold);color:#1b1206;font-size:14px;padding:6px 14px">YOUR STUDIO WON!</span></div>`:''}</div>${nomHTML(true)}`)+
 `<button class="btn gold" onclick="AW.i++;AW.rev=0;awStep()">Next award →</button><button class="btn ghost" onclick="awResults()">Skip to results</button>`;
 if(winner.me){sfx('win');document.body.insertAdjacentHTML('beforeend',confetti(70));setTimeout(()=>{const c=document.querySelector('.confetti');if(c)c.remove()},4000);
  if(pid&&Math.random()<.5)setTimeout(()=>{const s=$('.stage-in');if(s)s.insertAdjacentHTML('beforeend',`<div class="card" style="text-align:left;margin-top:8px"><small>Acceptance speech</small><p style="font-size:13px;font-style:italic">"I want to thank ${esc(S.ceo?S.ceo.n:'the studio')} and everyone at ${esc(S.name)} for believing in this film…"</p><small class="pos">+2 prestige</small></div>`);gainRep(2)},700)}
 window.scrollTo(0,0)}
function awResults(){clearTimeout(AW&&AW.tm);const A=AW;A.res.forEach(r=>{delete r._nom;delete r._ord});const wins=A.res.filter(r=>r.win);
 $('#app').innerHTML=hud()+stageBG(`<div class="lights">${A.top}</div>${wins.length?`<div class="trophy">🏆</div><h2>${wins.length} win${wins.length>1?'s':''}!</h2>`:'<h2>Results</h2>'}${A.res.map(r=>`<div class="nominee ${r.win?'win':''}"><div style="flex:1"><small>${r.cat}</small><div><b>${esc(r.film.title)}</b></div>${!r.win?`<small style="text-transform:none">Winner: ${esc(r.rival)}</small>`:''}</div>${r.win?'🏆':''}</div>`).join('')||'<p class="muted">No nominations.</p>'}`)+`<button class="btn gold" onclick="runQueue()">Continue →</button>`;window.scrollTo(0,0)}

/* ---------- TV wizard with episodes & release mode ---------- */
function startShow(){
 if(ev('wga'))return modal(`<h3>✊ Writers are on strike</h3><p class="muted" style="margin-top:6px">No new series until ${tLabel(S.ev.wga.until+1)}.</p><button class="btn ghost" onclick="modal()">OK</button>`);
 TW={step:0,pitch:null,writer:null,lead:null,cos:[],eps:8,epB:null,outlet:S.streaming?'own':'network',mode:'binge',epNames:[],cliff:[],acts:shuffle(S.people.actors.filter(a=>!busy(a))).slice(0,8).sort((a,b)=>b.star-a.star),wrs:shuffle(S.people.writers.filter(w=>!busy(w))).slice(0,4)};tvWiz()}
function tvWiz(){const back=`<button class="btn ghost" onclick="${TW.step?'TW.step--;tvWiz()':'render()'}">← ${TW.step?'Back':'Cancel'}</button>`;
 let h=hud()+`<div class="steps">${[0,1,2,3].map(i=>`<i class="${i<=TW.step?'on':''}"></i>`).join('')}</div>`;
 if(TW.step===0){const ps=pitches();h+=`<h2>Choose a pitch</h2>`+(ps.length?ps.map((p,i)=>`<div class="card opt ${TW.pitch===p?'sel':''}" onclick="TW.pitch=S.pitches[${i}];TW.writer=TW.pitch.writer;tvWiz()"><div class="row"><b>${TV_GENRES[p.genre].icon} ${esc(p.title)}</b><span class="muted">${M(p.cost)}</span></div><div class="muted" style="font-size:13px;margin-top:4px">${p.genre} · pitched by ${esc(pname(p.writer))} · ${(p.q/10).toFixed(1)}/10</div>${bar(p.q)}</div>`).join(''):'<p class="card muted">No pitches this month.</p>');
  h+=`<button class="btn gold" ${TW.pitch?'':'disabled'} onclick="TW.step=1;tvWiz()">Next →</button>`+back}
 else if(TW.step===1){W={script:{genre:'Drama'},_role:'writers'};const pw=person(TW.pitch.writer);const ws=[pw].concat(TW.wrs.filter(w=>w.id!==pw.id));
  h+=`<h2>Showrunner & star</h2><h3 style="margin:8px 0">✍️ Showrunner</h3>`+ws.map(w=>personCard(w,TW.writer===w.id,`TW.writer='${w.id}';tvWiz()`,false,lockC(w))).join('');W._role='actors';
  h+=`<h3 style="margin:12px 0 8px">⭐ Lead actor</h3>`+TW.acts.map(a=>personCard(a,TW.lead===a.id,`TW.lead=TW.lead==='${a.id}'?null:'${a.id}';TW.cos=TW.cos.filter(x=>x!=='${a.id}');tvWiz()`,true,lockA(a))).join('')+`<h3 style="margin:12px 0 8px">👥 Co-stars (up to 3) · ${TW.cos.length}/3</h3>`+TW.acts.filter(a=>a.id!==TW.lead).map(a=>personCard(a,TW.cos.includes(a.id),`tvCo('${a.id}')`,true,lockA(a))).join('');
  h+=`<button class="btn gold" ${TW.writer?'':'disabled'} onclick="TW.step=2;tvWiz()">Next →</button>`+back}
 else if(TW.step===2){const n=TW.eps;while(TW.epNames.length<n)TW.epNames.push('');TW.epNames.length=n;
  h+=`<h2>Episodes</h2><div class="card"><small>Number of episodes</small><div class="seg">${[6,8,10,13].map(k=>`<button class="${TW.eps===k?'on':''}" onclick="TW.eps=${k};tvWiz()">${k}</button>`).join('')}</div></div>
  <div class="card"><div class="row"><small>Episode titles</small><button class="btn sm ghost" style="margin:0" onclick="TW.epNames=TW.epNames.map(()=>epTitle());tvWiz()">🎲 Name all</button></div>${TW.epNames.map((e,i)=>`<div class="ep"><b style="width:22px">${i+1}</b><input type="text" maxlength="40" value="${esc(e)}" placeholder="Episode ${i+1}" onchange="TW.epNames[${i}]=this.value"><button class="btn sm ${TW.cliff[i]?'gold':'ghost'}" style="margin:0;padding:6px 8px" title="Cliffhanger" onclick="TW.cliff[${i}]=!TW.cliff[${i}];tvWiz()">❓</button></div>`).join('')}<p class="muted" style="font-size:12px;margin-top:6px">❓ = ends on a cliffhanger. Cliffhangers boost the next episode's viewers in weekly releases (2–3 per season is ideal).</p></div>
  <button class="btn gold" onclick="TW.step=3;tvWiz()">Next →</button>`+back}
 else{const g=TW.pitch.genre;const ideal=tvEpIdeal(g);if(TW.epB==null)TW.epB=+ideal.toFixed(1);const cost=TW.eps*TW.epB;
  h+=`<h2>Season plan</h2><div class="card"><div class="row"><small>Budget per episode</small><b id="eb">${M(TW.epB)}</b></div><input type="range" min="0.5" max="${Math.round(30*I())}" step="0.5" value="${TW.epB}" oninput="TW.epB=+this.value;document.getElementById('eb').textContent=M(TW.epB);document.getElementById('tc').textContent=M(TW.eps*TW.epB)"><p class="muted" style="font-size:12px">Typical ${g}: ${M(ideal)} per episode.</p></div>
  <div class="card"><small>Release style</small><div class="seg"><button class="${TW.mode==='binge'?'on':''}" onclick="TW.mode='binge';tvWiz()">📦 All at once<br><small>binge</small></button><button class="${TW.mode==='weekly'?'on':''}" onclick="TW.mode='weekly';tvWiz()">📅 Weekly<br><small>one per week</small></button></div><p class="muted" style="font-size:12px;margin-top:6px">${TW.mode==='binge'?'Huge launch spike and sign-ups, but buzz fades fast.':'Slower start, longer buzz, more social chatter. Cliffhangers pay off.'}</p></div>${tvSchedCard()}
  <div class="card"><small>Where it airs</small><div class="seg">${S.streaming?`<button class="${TW.outlet==='own'?'on':''}" onclick="TW.outlet='own';tvWiz()">📡 ${esc(S.streaming.name)}</button>`:''}<button class="${TW.outlet==='network'?'on':''}" onclick="TW.outlet='network';tvWiz()">Network TV</button><button class="${TW.outlet==='rival'?'on':''}" onclick="TW.outlet='rival';tvWiz()">Rival streamer</button></div></div>
  <div class="card"><div class="row"><b>Season cost</b><b id="tc">${M(cost)}</b></div></div>
  <button class="btn gold" onclick="TW.epNames=TW.epNames.map((e,i)=>e||'Episode '+(i+1));greenlightShow(TW);save();TAB='hq';render()">🟢 ORDER THE SERIES</button>`+back}
 $('#app').innerHTML=h;window.scrollTo(0,0)}
const EPW=[['The','A','Last','First','Broken','Silent','Burning','Hidden','Cold','Long'],['Night','Signal','Promise','Door','Storm','Lie','Goodbye','Reckoning','Return','Bargain','Witness','Crown']];
function epTitle(){return pick(EPW[0])+' '+pick(EPW[1])}
function showModal(id){const s=S.shows.find(x=>x.id===id);if(!s)return;const last=s.seasons[s.seasons.length-1];
 const epv=last&&last.epViews||[];const mx=Math.max(...epv,1);
 modal(`<div class="pcard"><div style="width:70px;height:105px;border-radius:6px;background:linear-gradient(160deg,#1a3a4a,#0d0b10);display:flex;align-items:center;justify-content:center;font-size:34px">${TV_GENRES[s.genre].icon}</div><div><h3>${esc(s.title)}</h3><p class="muted" style="font-size:13px">${s.genre} · ${s.eps} eps · ${s.mode==='weekly'?'weekly':'binge'}<br>${s.lead?esc(pname(s.lead)):''}</p>${last?`<span class="tag ${last.critic>=85?'hot':last.critic>=60?'good':'bad'}">${last.critic>=85&&last.views>20?'🔥 VIRAL HIT':last.critic>=65?'$ HIT':last.critic>=50?'★ STANDARD':'📉 FLOP'}</span>`:''}</div></div>
 ${epv.length?`<div class="card"><small>Viewers per episode (season ${last.n})</small><div class="chart">${epv.map((v,i)=>`<div style="height:${v/mx*100}%"><span>${i+1}${(s.cliff||[])[i]?'❓':''}</span></div>`).join('')}</div><div style="height:16px"></div></div>`:''}
 <div class="card">${(s.epNames||[]).map((e,i)=>`<div class="ep" style="font-size:13px"><b style="width:22px">${i+1}</b><span style="flex:1">${esc(e)}</span>${(s.cliff||[])[i]?'❓':''}</div>`).join('')}</div>
 <div class="card"><table><tr><th>Season</th><th class="r">Critics</th><th class="r">Views</th><th class="r">Fee</th></tr>${s.seasons.map(se=>`<tr><td>S${se.n}</td><td class="r">${se.critic}%</td><td class="r">${se.views}M</td><td class="r">${se.fee?M(se.fee):'—'}</td></tr>`).join('')||'<tr><td colspan=4 class="muted">Premieres '+tLabel(s.readyT)+'</td></tr>'}</table></div>
 ${s.renew?`<button class="btn gold" onclick="renewShow(${id},true);save();modal();render()">🔁 Renew for season ${s.season+1}</button><button class="btn ghost" onclick="renewShow(${id},false);save();modal();render()">✂️ Cancel</button>`:''}<button class="btn ghost" onclick="modal()">Close</button>`)}

/* ---------- Streaming donut on Empire tab ---------- */
const _viewEmpire=viewEmpire;
viewEmpire=function(){const sv=S.streaming;const items=[{n:TECH_STREAMER.n,v:TECH_STREAMER.subs,c:'#9b59ff'}].concat(S.rivals.filter(r=>r.alive&&r.svc).map(r=>({n:r.svc,v:r.subs,c:r.c})));if(sv&&svcLive())items.push({n:sv.name,v:Math.max(sv.subs,.5),c:'#00e0b0',me:1});
 const tot=sum(items,x=>x.v);
 return `<div class="card"><h3>🌍 Global streaming market</h3><small style="text-transform:none">${fmtN(tot)} subscribers worldwide</small><div class="row" style="margin-top:8px"><div>${donut(items,130)}</div><div style="flex:1">${items.sort((a,b)=>b.v-a.v).map(i=>`<div style="font-size:12px;margin:3px 0"><span style="display:inline-block;width:10px;height:10px;border-radius:50%;background:${i.c}"></span> ${i.me?'<b class="gold">'+esc(i.n)+' (you)</b>':esc(i.n)} · ${fmtN(i.v)} (${(i.v/tot*100).toFixed(1)}%)</div>`).join('')}</div></div>${sv&&svcLive()?'<p class="muted" style="font-size:12px;margin-top:6px">💡 Every giant started small. Keep adding quality films and shows.</p>':''}</div>`+_viewEmpire()}

function tvCo(id){if(TW.cos.includes(id))TW.cos=TW.cos.filter(x=>x!==id);else if(TW.cos.length<3)TW.cos.push(id);tvWiz()}
